func GetGuest(ctx context.Context, db *sql.DB, id string) (*Guest, error) {
    var g Guest
    err := db.QueryRowContext(ctx, "SELECT id, name FROM guests WHERE id = $1", id).Scan(&g.ID, &g.Name)
    if err != nil {
        return nil, fmt.Errorf("query guest: %w", err)
    }
    return &g, nil
}
